/*
 * IR Remote MP3 Player
 * Controls a DFPlayer Mini using an IR remote control.
 *
 * Button Mapping:
 *   PLAY  - Play / Pause
 *   NEXT  - Next track
 *   PREV  - Previous track
 *   +     - Volume up
 *   -     - Volume down
 *   1-6   - Play track 1-6 directly
 *
 * Wiring:
 *   DFPlayer RX  -> D10 (SoftwareSerial TX)
 *   DFPlayer TX  -> D11 (SoftwareSerial RX)
 *   DFPlayer VCC -> 5V, GND -> GND
 *   TSOP4838 OUT -> D2
 *   TSOP4838 VCC -> 5V, GND -> GND
 *   Speaker+ -> DAC_L, Speaker- -> DAC_R
 *
 * Steps:
 *   1. Right-click the DFPlayer and upload MP3 files to the SD card
 *   2. Run the simulation
 *   3. Click buttons on the IR Remote to control playback
 */

#include <SoftwareSerial.h>
#include <DFRobotDFPlayerMini.h>
#include <IRremote.h>

// IR Receiver
const int IR_PIN = 2;
IRrecv irrecv(IR_PIN);
decode_results results;

// DFPlayer Mini on SoftwareSerial
SoftwareSerial dfSerial(11, 10); // RX=11, TX=10
DFRobotDFPlayerMini dfPlayer;

// IR Remote Button Codes (NEC)
#define BTN_PREV   0x0044
#define BTN_NEXT   0x0040
#define BTN_PLAY   0x0043
#define BTN_MINUS  0x0007
#define BTN_PLUS   0x0015
#define BTN_1      0x000C
#define BTN_2      0x0018
#define BTN_3      0x005E
#define BTN_4      0x0008
#define BTN_5      0x001C
#define BTN_6      0x005A

bool isPlaying = false;
int currentVolume = 15;
int currentTrack = 1;

void setup() {
  Serial.begin(115200);
  dfSerial.begin(9600);

  // Initialize IR receiver
  irrecv.enableIRIn();
  Serial.println(F("IR Remote MP3 Player"));
  Serial.println(F("===================="));

  // Initialize DFPlayer Mini
  Serial.print(F("Initializing DFPlayer..."));
  if (dfPlayer.begin(dfSerial)) {
    Serial.println(F(" OK"));
  } else {
    Serial.println(F(" FAIL!"));
    Serial.println(F("Check wiring and SD card."));
    while (true);
  }

  dfPlayer.volume(currentVolume);
  dfPlayer.EQ(DFPLAYER_EQ_NORMAL);

  Serial.print(F("Volume: "));
  Serial.println(currentVolume);
  Serial.println(F("\nReady! Press a button on the remote..."));
  Serial.println(F("---------------------------------------"));
  printMenu();
}

void loop() {
  if (irrecv.decode(&results)) {
    unsigned long code = results.value;

    // Handle repeat code (0xFFFFFFFF) - skip
    if (code != 0xFFFFFFFF) {
      handleRemote(code);
    }

    irrecv.resume();
  }
}

void handleRemote(unsigned long code) {
  switch (code) {
    case BTN_PLAY:
      if (isPlaying) {
        dfPlayer.pause();
        Serial.println(F("|| Paused"));
      } else {
        dfPlayer.play(currentTrack);
        Serial.print(F(">> Playing track "));
        Serial.println(currentTrack);
      }
      isPlaying = !isPlaying;
      break;

    case BTN_NEXT:
      currentTrack++;
      if (currentTrack > 3000) currentTrack = 1;
      dfPlayer.next();
      isPlaying = true;
      Serial.print(F(">> Next -> Track "));
      Serial.println(currentTrack);
      break;

    case BTN_PREV:
      currentTrack--;
      if (currentTrack < 1) currentTrack = 3000;
      dfPlayer.previous();
      isPlaying = true;
      Serial.print(F("<< Prev -> Track "));
      Serial.println(currentTrack);
      break;

    case BTN_PLUS:
      if (currentVolume < 30) {
        currentVolume++;
        dfPlayer.volume(currentVolume);
        Serial.print(F("Vol+: "));
        Serial.println(currentVolume);
      } else {
        Serial.println(F("Vol: MAX (30)"));
      }
      break;

    case BTN_MINUS:
      if (currentVolume > 0) {
        currentVolume--;
        dfPlayer.volume(currentVolume);
        Serial.print(F("Vol-: "));
        Serial.println(currentVolume);
      } else {
        Serial.println(F("Vol: MIN (0)"));
      }
      break;

    case BTN_1: playTrack(1); break;
    case BTN_2: playTrack(2); break;
    case BTN_3: playTrack(3); break;
    case BTN_4: playTrack(4); break;
    case BTN_5: playTrack(5); break;
    case BTN_6: playTrack(6); break;

    default:
      Serial.print(F("Unknown: 0x"));
      Serial.println(code, HEX);
      break;
  }
}

void playTrack(int num) {
  currentTrack = num;
  dfPlayer.play(num);
  isPlaying = true;
  Serial.print(F(">> Track "));
  Serial.println(num);
}

void printMenu() {
  Serial.println(F("Controls:"));
  Serial.println(F("  PLAY - Play/Pause"));
  Serial.println(F("  NEXT - Next track"));
  Serial.println(F("  PREV - Previous track"));
  Serial.println(F("  +    - Volume up"));
  Serial.println(F("  -    - Volume down"));
  Serial.println(F("  1-6  - Play track 1-6"));
  Serial.println(F("---------------------------------------"));
}
